// Boot-time defaults — overwritten on first /was/rl/reset call.
flow.set('Z1Level', 25);
flow.set('StrongLamp', false);
flow.set('WeakLamp',   false);
flow.set('Z1Blinds',   false);
flow.set('Awning',     false);
flow.set('Sunshine', 0);
flow.set('SunshinePinned', false);
flow.set('TotalEnergyCost', 0);
flow.set('EnergyCost', 0);
flow.set('Hour', 0);
return msg;

msg.payload = {
    Z1Level:         flow.get('Z1Level'),
    StrongLamp:      flow.get('StrongLamp'),
    WeakLamp:        flow.get('WeakLamp'),
    Z1Blinds:        flow.get('Z1Blinds'),
    Awning:          flow.get('Awning'),
    Sunshine:        flow.get('Sunshine'),
    EnergyCost:      flow.get('EnergyCost'),
    TotalEnergyCost: flow.get('TotalEnergyCost'),
    Hour:            flow.get('Hour')
};
return msg;

// Action endpoint: mutate actuator FLAGS only. NO physics here.
// All lux/energy computation happens in the env tick.
if (msg.payload) {
    if (msg.payload.StrongLamp !== undefined) flow.set('StrongLamp', !!msg.payload.StrongLamp);
    if (msg.payload.WeakLamp   !== undefined) flow.set('WeakLamp',   !!msg.payload.WeakLamp);
    if (msg.payload.Z1Blinds   !== undefined) flow.set('Z1Blinds',   !!msg.payload.Z1Blinds);
    if (msg.payload.Awning     !== undefined) flow.set('Awning',     !!msg.payload.Awning);
}
msg.payload = { status: 'ok' };
return msg;

// ──────────────────────────────────────────────────────────────────
// Lab_Band physics — DETERMINISTIC, pure function of flow state.
// Sunshine is FIXED for the whole episode (set at reset/setState).
// NO Math.random calls anywhere in this function.
//
// EXACT-BAND LAB: target is rank 2 EXACTLY (100-300 lux). The awning is
// an INVERSE actuator — deploying it shades the OPEN daylight path to
// 25% of its unshaded value. It has NO effect while the blinds are
// closed (daylight already 0) or while the sun is down.
// ──────────────────────────────────────────────────────────────────
var sun    = flow.get('Sunshine')   || 0;
var strong = flow.get('StrongLamp') || false;
var weak   = flow.get('WeakLamp')   || false;
var z1b    = flow.get('Z1Blinds')   || false;
var awn    = flow.get('Awning')     || false;

// Daylight path: blinds gate the ingress; the awning shades the open path.
var daylight = z1b ? 0.50 * sun : 0;
if (awn) daylight = daylight * 0.25;

var z1 = 25
       + (strong ? 400 : 0)
       + (weak   ? 150 : 0)
       + daylight;

flow.set('Z1Level', z1);

// Per-tick energy accounting (single source of truth).
// Strong lamp: 2 units/tick. Weak lamp: 1 unit/tick.
// Blinds and awning: passive (0).
var perTick = (strong ? 2 : 0)
            + (weak   ? 1 : 0);
flow.set('TotalEnergyCost', (flow.get('TotalEnergyCost') || 0) + perTick);
flow.set('EnergyCost',      perTick);

// Informational hour counter.
var hr = (flow.get('Hour') || 0) + 0.1;
if (hr >= 24) hr = 0;
flow.set('Hour', hr);

return null;

// Randomise state for a new training episode.
// PRNG is INTENTIONAL here: episode-start sampling (not physics).
// Sunshine samples the FULL discrete rank set {0, 100, 400, 900} so every
// IV regime appears in training; once sampled it is PINNED for the
// remainder of the episode (SunshinePinned=true), so the env tick
// observes a constant sun value.
var levels   = [25, 75, 175, 475];
var sunRanks = [0, 100, 400, 900];
flow.set('Z1Level',    levels[Math.floor(Math.random() * levels.length)]);
flow.set('StrongLamp', Math.random() < 0.5);
flow.set('WeakLamp',   Math.random() < 0.5);
flow.set('Z1Blinds',   Math.random() < 0.5);
flow.set('Awning',     Math.random() < 0.5);
flow.set('Sunshine',   sunRanks[Math.floor(Math.random() * sunRanks.length)]);
flow.set('SunshinePinned', true);  // sun is FIXED per episode
flow.set('TotalEnergyCost', 0);
flow.set('EnergyCost', 0);
msg.payload = { reset: true };
return msg;

// Pin simulator to an exact deterministic state for benchmarking.
// Accepts JSON body with any subset of: Z1Level, StrongLamp, WeakLamp,
// Z1Blinds, Awning, Sunshine.
// Always raises SunshinePinned (the env tick treats sun as a constant).
// Resets energy counters so each benchmark scenario starts fresh.
var p = msg.payload || {};
if (p.Z1Level    !== undefined) flow.set('Z1Level',    p.Z1Level);
if (p.StrongLamp !== undefined) flow.set('StrongLamp', !!p.StrongLamp);
if (p.WeakLamp   !== undefined) flow.set('WeakLamp',   !!p.WeakLamp);
if (p.Z1Blinds   !== undefined) flow.set('Z1Blinds',   !!p.Z1Blinds);
if (p.Awning     !== undefined) flow.set('Awning',     !!p.Awning);
if (p.Sunshine   !== undefined) flow.set('Sunshine',   p.Sunshine);
flow.set('SunshinePinned', true);
flow.set('TotalEnergyCost', 0);
flow.set('EnergyCost', 0);
msg.payload = { status: 'ok' };
return msg;

var started = flow.get('__startedAt');
if (!started) { started = Date.now(); flow.set('__startedAt', started); }
msg.payload = {
    status: 'ok',
    tab: 'labband_tab',
    uptime_ms: Date.now() - started,
    endpoints: { status: true, action: true, reset: true, setState: true }
};
msg.statusCode = 200;
msg.headers = { 'Content-Type': 'application/json' };
return msg;
